import { LoginAside, LoginError, MagicLinkLogin } from '../components'
import { useClientContent } from '../contexts/ClientContent/context'
import useParsedUrlParams from '../hooks/useParsedUrlParams'
import { useRedirectIfExpired } from '../hooks/useRedirectIfExpired'
import styles from './index.module.scss'

export default function Index() {
  const { params, errors } = useParsedUrlParams('magic-link')
  const { clientDataError } = useClientContent()
  useRedirectIfExpired('magic-link')

  const errorList = () => {
    if (errors) {
      return errors
    }

    if (clientDataError) {
      // Remove empty strings from the array
      return [clientDataError.message].filter(Boolean)
    }
  }

  return (
    <>
      <article className={styles.article}>
        <div className={styles.container}>
          {errors || clientDataError ? (
            <LoginError status={clientDataError?.status} errors={errorList()} />
          ) : (
            <MagicLinkLogin params={params} />
          )}
        </div>
        <div className={styles.container}>
          <LoginAside />
        </div>
      </article>
    </>
  )
}
