import { isFuture } from 'date-fns'
import React from 'react'

import { useClientContent } from '../contexts/ClientContent/context'
import useParsedUrlParams from './useParsedUrlParams'

export function useRedirectIfExpired(
  loginType: 'qr-code' | 'magic-link',
): void {
  const { client } = useClientContent()
  const { params } = useParsedUrlParams(loginType)
  const redirectUrl = client.login_initiation_url
  const expiry = params?.expiry

  const redirectToInitiationUrl = React.useCallback(() => {
    // If we don't have an expiry or redirect URL, we can't redirect. The 'expiry' param is optional so it's a valid case.
    if (!expiry || !redirectUrl) return

    // If the expiry is in the future, we don't need to redirect because the login is still valid
    if (isFuture(expiry)) return

    // Don't redirect if the tab is hidden. It's wasteful because it seems they're not using the site, so we could just
    // end up redirecting them when they return to the tab anyway.
    if (window.document.visibilityState === 'hidden') return

    window.location.href = redirectUrl
  }, [expiry, redirectUrl])

  React.useEffect(() => {
    redirectToInitiationUrl()
  }, [redirectToInitiationUrl])

  React.useEffect(() => {
    if (!expiry || !redirectUrl) return
    window.addEventListener('visibilitychange', redirectToInitiationUrl, true)

    return () => {
      window.removeEventListener(
        'visibilitychange',
        redirectToInitiationUrl,
        true,
      )
    }
  }, [redirectToInitiationUrl, expiry, redirectUrl])
}
